const fs = require("fs");
const path = require("path");
const { createHash } = require("crypto");

const ROOT = path.join(__dirname, "..");
const OUT = path.join(ROOT, "src", "shared", "config", "cache-version.gen.ts");
const GEN_HEADER =
  "// Generated by build/gen-cache-version.cjs — do not edit.\n" +
  "// Git-ignored and rewritten by every entry point (npm run dev / type-check / test / build / format).\n" +
  "// CACHE_VERSION namespaces KV entries and moves with the project release (package.json version) and any server-side\n" +
  "// change; CONTRACT_VERSION names the payload shape the client compares against X-Contract-Version.\n";

const ROOTS = ["src/server", "src/shared"];

// What the API returns, and the only thing a client bundle has to agree with to read a response: the payload types,
// the domain → payload map, and the domain paths. Everything else server-side can change without a client noticing.
const CONTRACT_SOURCES = ["src/shared/types", "src/shared/contract.ts", "src/shared/config/api.ts"];

const EXCLUDED = [
  /\.test\.ts$/,
  /^src\/shared\/config\/cache-version\.gen\.ts$/,
  /^src\/shared\/i18n\//,
  /^src\/shared\/pwa\.ts$/,
  /^src\/shared\/config\/typography\.ts$/,
];

// Files the server never imports, so their content cannot affect a cached payload. `assertClientOnly` enforces that:
// a file listed here is hashed out of CACHE_VERSION, so the server importing one again would leave stale entries
// behind a deployment. `color.ts` is deliberately absent — `computeProviderStats` runs it for the home dashboard.
const CLIENT_ONLY = [
  "src/shared/utils/cost.ts",
  "src/shared/utils/hallucination.ts",
  "src/shared/utils/money.ts",
  "src/shared/utils/pricing.ts",
  "src/shared/utils/release-feed.ts",
  "src/shared/utils/text-format.ts",
];

const PINNED_DEPS = ["fast-xml-parser", "strnum"];

function fail(message) {
  console.error(`gen:cache-version ${message}`);
  process.exit(1);
}

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? walk(full) : [full];
  });
}

function relative(abs) {
  return path.relative(ROOT, abs).split(path.sep).join("/");
}

function hashedFiles() {
  return ROOTS.flatMap((root) => walk(path.join(ROOT, root)))
    .map((abs) => ({ abs, rel: relative(abs) }))
    .filter(({ rel }) => !EXCLUDED.some((pattern) => pattern.test(rel)) && !CLIENT_ONLY.includes(rel))
    .sort((a, b) => (a.rel < b.rel ? -1 : 1));
}

function contractFiles() {
  return CONTRACT_SOURCES.flatMap((entry) => {
    const abs = path.join(ROOT, entry);
    return fs.statSync(abs).isDirectory() ? walk(abs) : [abs];
  })
    .map((abs) => ({ abs, rel: relative(abs) }))
    .filter(({ rel }) => !rel.endsWith(".test.ts"))
    .sort((a, b) => (a.rel < b.rel ? -1 : 1));
}

function exportedNames(rel) {
  const source = fs.readFileSync(path.join(ROOT, rel), "utf8");
  const names = new Set();
  const declared = /^export\s+(?:async\s+)?(?:function|const|class|interface|type)\s+(\w+)/gm;
  for (const [, name] of source.matchAll(declared)) names.add(name);
  for (const [, body] of source.matchAll(/^export\s*\{([^}]*)\}/gm)) {
    for (const part of body.split(","))
      names.add(
        part
          .trim()
          .split(/\s+as\s+/)
          .pop(),
      );
  }
  return [...names].filter(Boolean);
}

/**
 * Comments are not references. The check used to scan the raw source, so a server comment that merely named an exported
 * helper failed the build; stripping comments first removes that whole class of false positive. A name inside a string
 * literal still matches, which is the conservative direction for an assertion about a leak.
 */
function stripComments(source) {
  return source.replace(/\/\*[\s\S]*?\*\//g, " ").replace(/(^|[^:])\/\/[^\n]*/g, "$1 ");
}

function assertClientOnly() {
  const server = walk(path.join(ROOT, "src", "server"))
    .filter((abs) => !abs.endsWith(".test.ts"))
    .map((abs) => ({ rel: relative(abs), src: stripComments(fs.readFileSync(abs, "utf8")) }));
  for (const rel of CLIENT_ONLY) {
    if (!fs.existsSync(path.join(ROOT, rel))) fail(`client-only file not found: ${rel}`);
    for (const name of exportedNames(rel)) {
      const hit = server.find((file) => new RegExp(`\\b${name}\\b`).test(file.src));
      if (hit) fail(`${rel} is client-only, but src/server references "${name}" in ${hit.rel}`);
    }
  }
}

function pinnedVersions() {
  const lock = JSON.parse(fs.readFileSync(path.join(ROOT, "package-lock.json"), "utf8"));
  return PINNED_DEPS.map((name) => {
    const version = lock.packages?.[`node_modules/${name}`]?.version;
    if (typeof version !== "string") fail(`package-lock.json has no resolved version for ${name}`);
    return `${name}@${version}`;
  });
}

/** The project release, read from package.json so `npm version` is the only place a bump is written. */
function projectVersion() {
  const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, "package.json"), "utf8"));
  if (typeof pkg.version !== "string" || pkg.version === "") fail("package.json has no version");
  return pkg.version;
}

function digest(entries) {
  const hash = createHash("sha256");
  for (const { key, source } of entries) hash.update(key).update("\0").update(source).update("\0");
  return `sha-${hash.digest("hex").slice(0, 12)}`;
}

/**
 * Everything a cached entry could depend on: the project release, parser code, cache code and the pinned parser
 * dependencies.
 *
 * The release number leads the digest so a version bump retires the previous KV generation by itself. Without it, a
 * release that changed only client code — or that a maintainer chose to cut without touching `src/server` — would keep
 * serving the old namespace, and "2.0.0" would be a label rather than a cache boundary. Entries written under the old
 * prefix stay until their `expirationTtl` expires; nothing reads them again.
 */
function cacheVersion() {
  return digest([
    { key: "release", source: projectVersion() },
    ...pinnedVersions().map((pinned) => ({ key: `dep:${pinned}`, source: "" })),
    ...hashedFiles().map(({ rel, abs }) => ({ key: rel, source: fs.readFileSync(abs, "utf8") })),
  ]);
}

function contractVersion() {
  return digest(contractFiles().map(({ rel, abs }) => ({ key: rel, source: fs.readFileSync(abs, "utf8") })));
}

/**
 * Writes the versions every bundle imports. Both hashes are derived from the sources they describe, so the file is
 * git-ignored and regenerated by each entry point instead of being committed and verified: a committed copy turned a
 * forgotten regeneration into a build failure that asked for a manual command — the one step this avoids.
 */
function main() {
  const args = process.argv.slice(2);
  if (args.length > 0) fail(`unknown argument: ${args.join(" ")}`);
  assertClientOnly();

  const cache = cacheVersion();
  const contract = contractVersion();
  const content = `${GEN_HEADER}export const CACHE_VERSION = "${cache}";\nexport const CONTRACT_VERSION = "${contract}";\n`;
  if (fs.existsSync(OUT) && fs.readFileSync(OUT, "utf8") === content) {
    console.log(`gen:cache-version ok (cache ${cache}, contract ${contract})`);
    return;
  }
  fs.writeFileSync(OUT, content);
  console.log(`gen:cache-version wrote ${relative(OUT)} (cache ${cache}, contract ${contract})`);
}

try {
  main();
} catch (err) {
  fail(err instanceof Error ? err.message : String(err));
}
